  "Set both voices together or tune {first} and {second} separately.": "Règle les deux voix ensemble, ou ajuste {first} et {second} séparément.",
  "{target} is ready to type. You can answer either box first; a correct {target} answer moves focus to {meaning}.": "Tu peux taper tout de suite en {target}. Tu peux commencer par le champ que tu veux ; une bonne réponse en {target} déplace le curseur vers le champ {meaning}.",
  "Type this in {language}": "Tape ceci en {language}",
